 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row if v != 0)
    if not counts:
        return [row[:] for row in grid]
    # The rare non-background color marks a stencil. Copy its exact shape
    # into other placements where all stencil cells are background.
    color = min(counts, key=counts.get)
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
    rmin = min(r for r, _ in cells)
    cmin = min(c for _, c in cells)
    shape = [(r-rmin, c-cmin) for r, c in cells]
    ph = max(r for r, _ in shape) + 1
    pw = max(c for _, c in shape) + 1
    out = [row[:] for row in grid]
    for r0 in range(h-ph+1):
        for c0 in range(w-pw+1):
            if all(grid[r0+r][c0+c] == 0 for r, c in shape):
                for r, c in shape:
                    out[r0+r][c0+c] = color
    return out

if __name__ == '__main__':
    pass
